&reftitle.description;
public Yaf_Route_InterfaceYaf_Router::getRoute stringname
Obtém uma rota pelo nome, consulte também Yaf_Router::getCurrentRoute

  &reftitle.examples;

   Exemplo de Yaf_Router::getRoute


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initRoutes(Yaf_Dispatcher $dispatcher)
    {
        $router = $dispatcher->getRouter();

        $router->addRoute("rewrite", new Yaf_Route_Rewrite(
            "/product/:id",
            ["controller" => "product", "action" => "detail"]
        ));

        /* verifica o que foi registrado sob um determinado nome */
        var_dump($router->getRoute("rewrite"));

        /* um nome desconhecido retorna NULL */
        var_dump($router->getRoute("unknown"));
    }
}
?>


